use crate::emon::align::*;
use crate::emon::model::*;

pub(crate) fn at_code(al: &mut crate::port::Cells, n: i32) -> i32 {
    // The code of the verdict on the n rows from row 0, 0 when it is below `align-min` or none.
    let v: i32 = al_judge(al, 0, n);
    if al_conf(v) < al_min() {
        return 0;
    }
    return al_code(v);
}
#[test]
fn test_every_row_of_the_table() {
    let al: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // justify: four lines flush at both edges (a hair off), the last flush at the start and short.
    al_line(al, 0, 40, 1000, 0);
    al_line(al, 20, 0, 1000, 0);
    al_line(al, 0, 30, 1000, 0);
    al_line(al, 10, 5400, 1000, 0);
    crate::testport::assert_eq(at_code(al, 4), al_justify(), "justify");
    crate::port::cells_drop(al, 0);
    // start: every S at the edge, the end edge ragged.
    al_line(al, 0, 1500, 1000, 0);
    al_line(al, 0, 800, 1000, 0);
    al_line(al, 0, 3000, 1000, 0);
    al_line(al, 0, 6000, 1000, 0);
    crate::testport::assert_eq(at_code(al, 4), al_start(), "start");
    crate::port::cells_drop(al, 0);
    // end: every E at the edge, the start edge ragged.
    al_line(al, 1500, 0, 1000, 0);
    al_line(al, 800, 0, 1000, 0);
    al_line(al, 3000, 0, 1000, 0);
    al_line(al, 600, 0, 1000, 0);
    crate::testport::assert_eq(at_code(al, 4), al_end(), "end");
    crate::port::cells_drop(al, 0);
    // center: S = E on every line, and the lines differ.
    al_line(al, 1000, 1000, 1000, 0);
    al_line(al, 2500, 2500, 1000, 0);
    al_line(al, 500, 500, 1000, 0);
    al_line(al, 3000, 3100, 1000, 0);
    crate::testport::assert_eq(at_code(al, 4), al_center(), "center");
    crate::port::cells_drop(al, 0);
    // a first-line indent comes out of line 1's S: the block is start, not none.
    al_line(al, 1500, 1800, 1000, 0);
    al_line(al, 0, 900, 1000, 0);
    al_line(al, 0, 2600, 1000, 0);
    al_line(al, 0, 5000, 1000, 0);
    crate::testport::assert_eq(at_code(al, 4), al_start(), "an indented first line");
    crate::port::cells_drop(al, 0);
    // a justified block with an indented first line is justify.
    al_line(al, 1500, 0, 1000, 0);
    al_line(al, 0, 0, 1000, 0);
    al_line(al, 0, 0, 1000, 0);
    al_line(al, 0, 4000, 1000, 0);
    crate::testport::assert_eq(at_code(al, 4), al_justify(), "justify with an indent");
}
#[test]
fn test_what_has_no_verdict() {
    let al: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // Two lines, both flush at both edges: not enough to say justify (one non-last line), and not start, end or center.
    al_line(al, 0, 0, 1000, 0);
    al_line(al, 0, 4000, 1000, 0);
    crate::testport::assert_eq(at_code(al, 2), 0, "two lines");
    crate::port::cells_drop(al, 0);
    // A block that wanders: S and E both vary, S - E does not hold.
    al_line(al, 0, 3000, 1000, 0);
    al_line(al, 2000, 100, 1000, 0);
    al_line(al, 700, 4000, 1000, 0);
    al_line(al, 0, 100, 1000, 0);
    crate::testport::assert_eq(at_code(al, 4), 0, "no pattern");
    crate::port::cells_drop(al, 0);
    crate::testport::assert_eq(al_judge(al, 0, 0), 0, "no lines");
}
#[test]
fn test_a_single_line() {
    let al: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // Centred: S and E at least four t, and within t of each other.
    al_line(al, 5000, 5100, 1000, 0);
    crate::testport::assert_eq(at_code(al, 1), al_center(), "a centred line");
    crate::port::cells_drop(al, 0);
    // At the end edge, started two body sizes in.
    al_line(al, 9000, 0, 1000, 0);
    crate::testport::assert_eq(at_code(al, 1), al_end(), "a line at the end edge");
    crate::port::cells_drop(al, 0);
    // At the end edge but started only a body size in: an indented line that happens to fill its row.
    al_line(al, 1200, 0, 1000, 0);
    crate::testport::assert_eq(at_code(al, 1), 0, "an indented full line is not right-aligned");
    crate::port::cells_drop(al, 0);
    // Flush at the start: `start`, but below `align-min`, for the second pass (the class) to decide.
    al_line(al, 0, 5000, 1000, 0);
    crate::testport::assert_eq(al_code(al_judge(al, 0, 1)), al_start(), "a flush-start line, tentatively start");
    crate::testport::assert_eq(at_code(al, 1), 0, "and not written on its own");
}
#[test]
fn test_the_second_pass_follows_the_style_class() {
    let al: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(nodes, attrs, regions, text, pages, ledger, layout);
    // Block 1: a start block of 4 lines in the 10 pt class; block 2: a single flush-start line of the same class
    // (start, it follows its peers); block 3: a single flush-start line of 20 pt, a class with no multi-line block
    // (a heading: start); block 4: a justified block of 4 lines in the 9 pt bold class and block 5 a single
    // flush-start line of that class (the last line of a justified block, perhaps: none); block 6: a centred line.
    let b1: i32 = node_new(nodes, nk_paragraph(), 0);
    let b2: i32 = node_new(nodes, nk_paragraph(), 0);
    let b3: i32 = node_new(nodes, nk_paragraph(), 0);
    let b4: i32 = node_new(nodes, nk_paragraph(), 0);
    let b5: i32 = node_new(nodes, nk_paragraph(), 0);
    let b6: i32 = node_new(nodes, nk_paragraph(), 0);
    al_line(al, 0, 1500, 1000, 0);
    al_line(al, 0, 800, 1000, 0);
    al_line(al, 0, 3000, 1000, 0);
    al_line(al, 0, 6000, 1000, 0);
    al_mark(al, b1);
    al_line(al, 0, 4000, 1000, 0);
    al_mark(al, b2);
    al_line(al, 0, 4000, 2000, 0);
    al_mark(al, b3);
    al_line(al, 0, 40, 900, 1);
    al_line(al, 20, 0, 900, 1);
    al_line(al, 0, 30, 900, 1);
    al_line(al, 10, 5400, 900, 1);
    al_mark(al, b4);
    al_line(al, 0, 4000, 900, 1);
    al_mark(al, b5);
    al_line(al, 5000, 5100, 1000, 0);
    al_mark(al, b6);
    crate::testport::assert_eq(al_pass(nodes, attrs, al, cl), 5, "five blocks got an align");
    crate::testport::assert_eq(node_sub(nodes, b1), al_start(), "the multi-line start block");
    crate::testport::assert_eq(node_sub(nodes, b2), al_start(), "a single line follows a class of start blocks");
    crate::testport::assert_eq(node_sub(nodes, b3), al_start(), "a single line in a class with no multi-line block");
    crate::testport::assert_eq(node_sub(nodes, b4), al_justify(), "the justified block");
    crate::testport::assert_eq(node_sub(nodes, b5), 0, "a single line in a class of justified blocks gets none");
    crate::testport::assert_eq(node_sub(nodes, b6), al_center(), "a centred line");
}
